BEGIN; SET LOCAL statement_timeout='8s'; SET LOCAL lock_timeout='1s';
SELECT population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
DO $review$ DECLARE r jsonb;id bigint; BEGIN
SELECT event_id,details INTO STRICT id,r FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='FINITE_CAPACITY_RENEWAL_DISTINCT_REVIEW_V1' AND details->>'candidate_event_id'='148564' AND details->>'actual_run_id'='167a5ae8-7608-8331-b3b5-ec5d1b26ef4b' AND details->>'approved'='true';
IF r->>'reviewer' IS DISTINCT FROM '/root/capacity_distinct_review' OR r->>'producer' IS DISTINCT FROM '/root' OR r->>'core_sha256' IS DISTINCT FROM '45990835ee1ed6a52f7ce58342949bdf6b10558ac21477d4c63001abc96f6688' OR ((r->>'not_after')::timestamptz>clock_timestamp()) IS DISTINCT FROM true OR r->>'claim_event_id' IS DISTINCT FROM '148292' OR r->>'new_source_limit' IS DISTINCT FROM '3000000000' OR r->>'new_tick_limit' IS DISTINCT FROM '100000' THEN RAISE EXCEPTION 'EXACT_CAPACITY_DISTINCT_REVIEW_REQUIRED';END IF;
IF (current_setting('data_directory') LIKE '/data/%') IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.resource_probe_v9 v CROSS JOIN LATERAL jsonb_array_elements(v.result->'metrics') z WHERE v.probe_id='1437c19c-2d2f-4a74-be5a-f6393efdc468' AND v.result_sha256='6e70f1a3ac480f512d55fdd920a4d73e6f1db41ac4c2dc665dfccc8276d4ca95' AND z->>'mountpoint'='/data' AND jsonb_typeof(z->'available_bytes')='number' AND (z->>'available_bytes')::numeric=152218886144) THEN RAISE EXCEPTION 'EXACT_DATA_MOUNT_PROOF_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='resource:d1925df378b9fe959083cf51e796ca77b0266a4ec4fd2d6f96ccf6acc79568c1' AND status='CLAIMED' AND claim_expires_at>clock_timestamp() AND input_sha256='d1925df378b9fe959083cf51e796ca77b0266a4ec4fd2d6f96ccf6acc79568c1') THEN RAISE EXCEPTION 'CURRENT_NATIVE_CAPACITY_CLAIM_REQUIRED';END IF;
PERFORM set_config('mission.capacity_review_id',id::text,true);
END $review$;
DO $renew$ DECLARE a jsonb;p jsonb;aa jsonb;pp jsonb;h jsonb;hh jsonb;disk numeric;rels bigint;def text; BEGIN
PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT to_jsonb(x) INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control x WHERE singleton FOR UPDATE;
SELECT to_jsonb(x) INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control x WHERE singleton FOR UPDATE;
IF a->>'scope_sha256' IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR a->>'max_source_bytes' IS DISTINCT FROM '2300000000' OR p->>'max_ticks' IS DISTINCT FROM '90000' OR p#>>'{budget_evidence,resource_limits,max_source_bytes}' IS DISTINCT FROM '2300000000' OR p#>>'{budget_evidence,resource_limits,max_total_ticks}' IS DISTINCT FROM '90000' OR p#>>'{budget_evidence,execution_continuation_policy,authority_event_id}' IS DISTINCT FROM '81090' OR clock_timestamp()>='2026-10-28T10:36:00Z' THEN RAISE EXCEPTION 'CAPACITY_CURRENT_PREIMAGE_REQUIRED'; END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event c JOIN population_top3000_202608_202609_v1.pipeline_event ass ON ass.event_id=145456 WHERE c.event_id=148292 AND c.event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND c.details->>'assignment_event_id'='145456' AND c.details->>'automation_run_id'='167a5ae8-7608-8331-b3b5-ec5d1b26ef4b' AND c.details->>'assignment_details_sha256'=encode(sha256(convert_to(ass.details::text,'UTF8')),'hex') AND c.details->>'owner_id'=a->>'owner_id' AND c.details->>'owner_fence'=a->>'owner_fence' AND c.details->>'stop_generation'=a->>'stop_generation' AND c.details->>'scope_sha256'=a->>'scope_sha256' AND (c.details->>'expires_at')::timestamptz>clock_timestamp() AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event d WHERE d.event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND d.details->>'claim_event_id'='148292' AND d.details->>'effects_known'='true')) THEN RAISE EXCEPTION 'CAPACITY_CURRENT_CLAIM_REQUIRED';END IF;
SELECT (z->>'available_bytes')::numeric INTO STRICT disk FROM population_top3000_202608_202609_v1.resource_probe_v9 v CROSS JOIN LATERAL jsonb_array_elements(v.result->'metrics') z WHERE v.probe_id='1437c19c-2d2f-4a74-be5a-f6393efdc468' AND v.state='SUCCEEDED' AND v.result_sha256='6e70f1a3ac480f512d55fdd920a4d73e6f1db41ac4c2dc665dfccc8276d4ca95' AND v.result_sha256=encode(sha256(convert_to(v.result::text,'UTF8')),'hex') AND (v.result->>'observed_at')::timestamptz>clock_timestamp()-interval '15 minutes' AND z->>'mountpoint'='/data';
SELECT sum(pg_total_relation_size(c.oid)) INTO rels FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND c.relkind IN('r','m');
IF disk<20000000000+4*(3000000000-(a->>'stored_bytes')::bigint)+(36000000000-rels) OR rels>36000000000 OR (a->>'stored_bytes')::bigint+(a->>'reserved_bytes')::bigint>2300000000 OR (p->>'tick_count')::bigint>=90000 THEN RAISE EXCEPTION 'CAPACITY_MEASURED_HEADROOM_REQUIRED';END IF;
SELECT pg_get_constraintdef(oid) INTO STRICT def FROM pg_constraint WHERE conrelid='population_top3000_202608_202609_v1.acquisition_control'::regclass AND conname='acquisition_control_max_source_bytes_check';
IF def IS DISTINCT FROM 'CHECK (((max_source_bytes >= 0) AND (max_source_bytes <= ''2300000000''::bigint)))' THEN RAISE EXCEPTION 'CAPACITY_CONSTRAINT_PREIMAGE_CHANGED';END IF;
SELECT to_jsonb(x) INTO STRICT h FROM population_top3000_202608_202609_v1.continuation_handler_v6 x WHERE kind='CTX02_PAGE_ADMISSION';
ALTER TABLE population_top3000_202608_202609_v1.acquisition_control DROP CONSTRAINT acquisition_control_max_source_bytes_check;
ALTER TABLE population_top3000_202608_202609_v1.acquisition_control ADD CONSTRAINT acquisition_control_max_source_bytes_check CHECK(max_source_bytes>=0 AND max_source_bytes<=3000000000::bigint);
UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_source_bytes=3000000000 WHERE singleton;
UPDATE population_top3000_202608_202609_v1.pipeline_control SET max_ticks=100000,budget_evidence=jsonb_set(jsonb_set(budget_evidence,'{resource_limits,max_source_bytes}','3000000000'::jsonb),'{resource_limits,max_total_ticks}','100000'::jsonb) WHERE singleton;
SELECT to_jsonb(x) INTO STRICT aa FROM population_top3000_202608_202609_v1.acquisition_control x WHERE singleton;
SELECT to_jsonb(x) INTO STRICT pp FROM population_top3000_202608_202609_v1.pipeline_control x WHERE singleton;
SELECT to_jsonb(x) INTO STRICT hh FROM population_top3000_202608_202609_v1.continuation_handler_v6 x WHERE kind='CTX02_PAGE_ADMISSION';
IF aa-'max_source_bytes' IS DISTINCT FROM a-'max_source_bytes' OR pp-'max_ticks'-'budget_evidence' IS DISTINCT FROM p-'max_ticks'-'budget_evidence' OR (pp->'budget_evidence')#-'{resource_limits,max_source_bytes}'#-'{resource_limits,max_total_ticks}' IS DISTINCT FROM (p->'budget_evidence')#-'{resource_limits,max_source_bytes}'#-'{resource_limits,max_total_ticks}' OR h IS DISTINCT FROM hh THEN RAISE EXCEPTION 'CAPACITY_UNRELATED_STATE_CHANGED';END IF;
PERFORM set_config('mission.capacity_receipt',jsonb_build_object('owner_id',a->>'owner_id','owner_fence',3,'stop_generation',1,'scope_sha256',a->>'scope_sha256','actual_run_id','167a5ae8-7608-8331-b3b5-ec5d1b26ef4b','assignment_event_id',145456,'claim_event_id',148292,'authority_event_id',81090,'monetary_authority_event_id',9528,'probe_id','1437c19c-2d2f-4a74-be5a-f6393efdc468','probe_result_sha256','6e70f1a3ac480f512d55fdd920a4d73e6f1db41ac4c2dc665dfccc8276d4ca95','disk_available',disk,'relation_bytes',rels,'old_source_limit',2300000000,'new_source_limit',3000000000,'old_tick_limit',90000,'new_tick_limit',100000,'counters',jsonb_build_object('stored',a->'stored_bytes','reserved',a->'reserved_bytes','provider',a->'provider_requests','http',a->'http_invocations','dispatch',a->'dispatch_calls','ticks',p->'tick_count'),'original_deadline_preserved',true,'cumulative_counters_preserved',true,'all_other_control_fields_preserved',true,'ctx02_handler_and_policies_unchanged',true,'source_admission_required_separately',true,'no_source_calls',true,'no_worker_or_function_change',true)::text,true);
END $renew$;

INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('FINITE_CAPACITY_RENEWAL_DEPLOYED_V1',current_setting('mission.capacity_receipt')::jsonb||jsonb_build_object('candidate_event_id',148564,'core_sha256','45990835ee1ed6a52f7ce58342949bdf6b10558ac21477d4c63001abc96f6688','independent_review_event_id',current_setting('mission.capacity_review_id')::bigint,'effects_known',true)) RETURNING event_id,details;
